function calculateGridLevels(midPrice, rangePercent, gridLevels, totalLiquidity, distribution) {
  const levels = [];
  const priceStep = midPrice * (rangePercent / 100) / gridLevels;
  const getWeight = (distanceFromMid) => {
    switch (distribution) {
      case "uniform":
        return 1;
      case "concentrated":
        return 1 / (distanceFromMid + 1);
      case "bell":
        return Math.exp(-0.5 * Math.pow(distanceFromMid / (gridLevels / 2), 2));
      default:
        return 1;
    }
  };
  let totalWeight = 0;
  for (let i = 1; i <= gridLevels; i++) {
    totalWeight += getWeight(i) * 2;
  }
  for (let i = gridLevels; i >= 1; i--) {
    const price = midPrice - priceStep * i;
    const weight = getWeight(i);
    const liquidity = totalLiquidity * weight / totalWeight;
    levels.push({
      price,
      liquidity,
      side: "bid",
      percentage: weight / totalWeight * 100 * gridLevels
    });
  }
  for (let i = 1; i <= gridLevels; i++) {
    const price = midPrice + priceStep * i;
    const weight = getWeight(i);
    const liquidity = totalLiquidity * weight / totalWeight;
    levels.push({
      price,
      liquidity,
      side: "ask",
      percentage: weight / totalWeight * 100 * gridLevels
    });
  }
  return levels;
}
